import React from 'react'
import { cn } from '../../lib/cn'

const STATUS_CONFIG = {
  available:  { label: 'Available',  className: 'bg-blue-50 text-blue-700 border-blue-200' },
  pending:    { label: 'Pending',    className: 'bg-amber-50 text-amber-700 border-amber-200' },
  claimed:    { label: 'Claimed',    className: 'bg-indigo-50 text-indigo-700 border-indigo-200' },
  accepted:   { label: 'In Progress', className: 'bg-ceda-green-pale text-ceda-forest border-ceda-green/30' },
  completed:  { label: 'Completed', className: 'bg-green-50 text-green-700 border-green-200' },
  declined:   { label: 'Declined',  className: 'bg-ceda-red-pale text-ceda-red border-ceda-red/20' },
  cancelled:  { label: 'Cancelled', className: 'bg-slate-100 text-slate-500 border-slate-200' },
}

export default function AssignmentStatusBadge({ status, className }) {
  const cfg = STATUS_CONFIG[status] ?? { label: status ?? 'Unknown', className: 'bg-slate-100 text-slate-500 border-slate-200' }
  return (
    <span className={cn(
      'inline-flex items-center px-2 py-0.5 rounded-full text-[11px] font-semibold border',
      cfg.className, className
    )}>
      {cfg.label}
    </span>
  )
}

export const TERMINAL_STATUSES = new Set(['completed', 'declined', 'cancelled'])

export function statusGroup(status) {
  if (['available', 'pending'].includes(status)) return 'pending'
  if (['claimed', 'accepted'].includes(status))  return 'inprogress'
  return 'done'
}

import { createContext, useContext, useState, useEffect, useCallback } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { auth as authApi } from '../api/endpoints'
import { TOKEN_KEY, REFRESH_KEY } from '../api/client'

const USER_KEY = 'ceda_innovation_user'
const ROLE_KEY = 'ceda_active_role'

const AuthContext = createContext(null)

function decodeJwt(token) {
  try { return JSON.parse(atob(token.split('.')[1])) } catch { return {} }
}

function normaliseRoles(rawRoles) {
  return (rawRoles ?? []).map(r => (r === 'admin' ? 'administrator' : r))
}

function normaliseProfile(profile, token) {
  if (!profile) return null
  const { user, ...profileFields } = profile
  const jwtClaims = token ? decodeJwt(token) : {}
  const roles     = normaliseRoles(jwtClaims.roles ?? user?.roles ?? [])
  return {
    ...user,
    roles,
    // From the server, for display only (Settings badge). Access uses can() (S1).
    is_admin:     Boolean(user?.is_admin ?? user?.is_superuser),
    is_staff:     Boolean(user?.is_staff),
    is_superuser: user?.is_superuser,
    profile: profileFields,
  }
}

function normaliseLoginUser(userData, token) {
  if (!userData) return null
  const jwtClaims = token ? decodeJwt(token) : {}
  const roles     = normaliseRoles(jwtClaims.roles ?? userData.roles ?? [])
  return {
    ...userData,
    roles,
    // From the server, for display only (Settings badge). Access uses can() (S1).
    is_admin:     Boolean(userData?.is_admin ?? userData?.is_superuser),
    is_staff:     Boolean(userData?.is_staff),
    is_superuser: userData.is_superuser,
    profile:      userData.profile ?? {},
  }
}

/**
 * What the person may do (S1), from GET /api/auth/me/. The API decides every request on its own; these only
 * decide what the console shows, so nobody is offered something the server will refuse.
 * `undefined` means "not known yet" (an old cached user, or me has not answered).
 */
function capabilitiesOf(data) {
  return Array.isArray(data?.capabilities) ? data.capabilities : undefined
}

async function loadUser(token, signal) {
  const [profile, me] = await Promise.all([
    authApi.me(signal),
    authApi.whoami(signal).catch((err) => {
      if (err?.name === 'AbortError') throw err
      return null
    }),
  ])
  if (profile == null) return null
  const normalised = normaliseProfile(profile, token)
  return { ...normalised, is_admin: Boolean(me?.is_admin ?? normalised.is_admin), capabilities: capabilitiesOf(me) }
}

function loadCachedUser() {
  try {
    const raw = localStorage.getItem(USER_KEY)
    return raw ? JSON.parse(raw) : null
  } catch {
    return null
  }
}

function loadActiveRole() {
  try {
    return localStorage.getItem(ROLE_KEY)
  } catch {
    return null
  }
}

export function AuthProvider({ children }) {
  const queryClient = useQueryClient()
  const [user, setUser]       = useState(() => loadCachedUser())
  const [activeRole, setActiveRole] = useState(() => loadActiveRole())
  const [loading, setLoading] = useState(() => !!localStorage.getItem(TOKEN_KEY))

  useEffect(() => {
    const token = localStorage.getItem(TOKEN_KEY)
    if (!token) {
      setLoading(false)
      return
    }

    const controller = new AbortController()
    const timeoutId  = setTimeout(() => controller.abort(), 10_000)
    let   unmounted  = false

    loadUser(localStorage.getItem(TOKEN_KEY), controller.signal)
      .then(normalised => {
        if (normalised == null) return
        setUser(normalised)
        localStorage.setItem(USER_KEY, JSON.stringify(normalised))
        if (normalised?.roles?.length) {
          setActiveRole((prev) => {
            const next = prev && normalised.roles.includes(prev) ? prev : normalised.roles[0]
            if (next) localStorage.setItem(ROLE_KEY, next)
            return next
          })
        }
      })
      .catch(err => {
        if (err?.name === 'AbortError') return
        console.warn('[AuthContext] profile refresh failed:', err.message)
      })
      .finally(() => {
        clearTimeout(timeoutId)
        if (!unmounted) setLoading(false)
      })

    return () => {
      unmounted = true
      controller.abort()
      clearTimeout(timeoutId)
    }
  }, [])

  const login = useCallback(async (email, password) => {
    const tokens = await authApi.login({ email, password })
    if (tokens?.mfa_required) throw new Error('This account uses two-step verification. Please sign in through the main portal.')
    if (!tokens?.access) throw new Error('Login failed: no token received.')

    localStorage.setItem(TOKEN_KEY, tokens.access)
    if (tokens.refresh) localStorage.setItem(REFRESH_KEY, tokens.refresh)

    let normalised
    if (tokens.user) {
      normalised = normaliseLoginUser(tokens.user, tokens.access)
      if (!capabilitiesOf(normalised)) {
        const me = await authApi.whoami().catch(() => null)
        normalised = { ...normalised, capabilities: capabilitiesOf(me) }
      }
    } else {
      normalised = await loadUser(tokens.access)
    }

    setUser(normalised)
    localStorage.setItem(USER_KEY, JSON.stringify(normalised))
    if (normalised?.roles?.length) {
      const next = activeRole && normalised.roles.includes(activeRole) ? activeRole : normalised.roles[0]
      if (next) {
        setActiveRole(next)
        localStorage.setItem(ROLE_KEY, next)
      }
    }
    return normalised
  }, [activeRole])

  const logout = useCallback(async () => {
    const refresh = localStorage.getItem(REFRESH_KEY)
    try { await authApi.logout(refresh ? { refresh } : undefined) } catch (_) {  }
    localStorage.removeItem(TOKEN_KEY)
    localStorage.removeItem(REFRESH_KEY)
    localStorage.removeItem(USER_KEY)
    localStorage.removeItem(ROLE_KEY)
    setUser(null)
    setActiveRole(null)
    // Nothing the last person could see stays in memory for the next one (S1). Capabilities come from user.
    queryClient.clear()
  }, [queryClient])

  const refreshUser = useCallback(async () => {
    try {
      const normalised = await loadUser(localStorage.getItem(TOKEN_KEY))
      if (normalised == null) return
      setUser(normalised)
      localStorage.setItem(USER_KEY, JSON.stringify(normalised))
    } catch (_) {  }
  }, [])

  // Ask for a capability, never a role name (ceda-security). Superusers get every capability from the API.
  const capabilities = user?.capabilities
  const can = useCallback((capability) => Array.isArray(capabilities) && capabilities.includes(capability), [capabilities])
  const canAny = useCallback((list) => list.some((c) => can(c)), [can])

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshUser, activeRole, setActiveRole, capabilities, can, canAny }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  return useContext(AuthContext)
}

import React, { useState, useEffect } from 'react'
import { useNavigate, useSearchParams } from 'react-router-dom'
import { Plus, FileText, Trophy, Megaphone, Star } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import PageHeader from '../../components/ui/PageHeader'
import StatusPill from '../../components/ui/StatusPill'
import EmptyState from '../../components/ui/EmptyState'
import ErrorState from '../../components/ui/ErrorState'
import Tabs from '../../components/ui/Tabs'
import { SkeletonCards } from '../../components/ui/LoadingSkeleton'
import { content } from '../../lib/api/endpoints'
import { cn } from '../../lib/cn'
import LeadershipList from './LeadershipManager'
import FaqList from './FaqManager'

const CATEGORY_COLOR = {
  announcement:    'bg-blue-50 text-blue-700',
  challenge_update:'bg-green-50 text-green-700',
  winners:         'bg-yellow-50 text-yellow-700',
  partnership:     'bg-purple-50 text-purple-700',
  success_story:   'bg-orange-50 text-orange-700',
}

const CATEGORY_LABEL = {
  announcement:    'Announcement',
  challenge_update:'Challenge Update',
  winners:         'Winners',
  partnership:     'Partnership',
  success_story:   'Success Story',
}

const TABS = [
  { key: 'news',       label: 'News & Articles' },
  { key: 'hackathons', label: 'Hackathon Pages' },
  { key: 'winners',    label: 'Winners' },
  { key: 'leadership', label: 'Leadership Carousel' },
  { key: 'faqs',       label: 'FAQs' },
]

function NewsCard({ item, onClick }) {
  return (
    <div onClick={onClick} className="card-hover cursor-pointer overflow-hidden flex flex-col">
      <div className="h-1.5 flex-shrink-0 bg-ceda-green" />
      <div className="p-5 flex flex-col flex-1">
        <div className="flex items-start justify-between gap-2 mb-3">
          <span className={cn('badge text-[11px]', CATEGORY_COLOR[item.category] ?? 'bg-ceda-surface text-ceda-muted')}>
            {CATEGORY_LABEL[item.category] ?? item.category}
          </span>
          <div className="flex items-center gap-1.5">
            {item.is_highlighted && (
              <span className="badge bg-amber-50 text-amber-700 text-[11px]">
                <Star size={10} className="mr-0.5 inline" />
                {item.highlight_priority ? `Homepage #${item.highlight_priority}` : 'Highlighted'}
              </span>
            )}
            <StatusPill status={item.status} />
          </div>
        </div>
        <h3 className="text-sm font-semibold text-ceda-dark mb-1 line-clamp-2 flex-1">{item.title}</h3>
        <p className="text-xs text-ceda-muted line-clamp-2 mb-4">{item.excerpt}</p>
        <div className="flex items-center justify-between pt-3 border-t border-ceda-border/60 text-[11px] text-ceda-muted">
          <span>{item.read_time || '—'}</span>
          <span>{item.published_at ? new Date(item.published_at).toLocaleDateString() : 'Not published'}</span>
        </div>
      </div>
    </div>
  )
}

function HackathonCard({ item, onClick }) {
  return (
    <div onClick={onClick} className="card-hover cursor-pointer overflow-hidden flex flex-col">
      <div className="h-1.5 flex-shrink-0 bg-amber-500" />
      <div className="p-5 flex flex-col flex-1">
        <div className="flex items-center justify-between gap-2 mb-3">
          <span className="badge bg-amber-50 text-amber-700 text-[11px]">Hackathon Page</span>
          <StatusPill status={item.is_published ? 'published' : 'draft'} />
        </div>
        <h3 className="text-sm font-semibold text-ceda-dark mb-1 line-clamp-2 flex-1">{item.program_title}</h3>
        <p className="text-xs text-ceda-muted line-clamp-2 mb-4">{item.theme || 'No theme set'}</p>
        <div className="flex items-center justify-between pt-3 border-t border-ceda-border/60 text-[11px] text-ceda-muted">
          <span>{(item.media ?? []).length} media file{item.media?.length !== 1 ? 's' : ''}</span>
          <span>{item.faq?.length ?? 0} FAQ{item.faq?.length !== 1 ? 's' : ''}</span>
        </div>
      </div>
    </div>
  )
}

function WinnerCard({ item, onClick }) {
  return (
    <div onClick={onClick} className="card-hover cursor-pointer overflow-hidden flex flex-col">
      <div className="h-1.5 flex-shrink-0 bg-yellow-500" />
      <div className="p-5 flex flex-col flex-1">
        <div className="flex items-center justify-between gap-2 mb-3">
          <span className="badge bg-yellow-50 text-yellow-700 text-[11px]">{item.position_display}</span>
          {item.is_featured && (
            <span className="badge bg-amber-50 text-amber-700 text-[11px]">
              <Star size={10} className="mr-0.5 inline" />Featured
            </span>
          )}
        </div>
        <h3 className="text-sm font-semibold text-ceda-dark mb-0.5">{item.team_name}</h3>
        <p className="text-xs text-ceda-muted mb-1">{item.project_name}</p>
        <p className="text-[11px] text-ceda-muted line-clamp-2 flex-1">{item.description}</p>
        <div className="flex items-center justify-between pt-3 mt-3 border-t border-ceda-border/60 text-[11px] text-ceda-muted">
          <span>{item.program_title}</span>
          <span>{item.year}</span>
        </div>
      </div>
    </div>
  )
}

export default function ContentList() {
  const navigate = useNavigate()
  const [searchParams, setSearchParams] = useSearchParams()
  const [tab, setTab] = useState(searchParams.get('tab') || 'news')

  useEffect(() => {
    const t = searchParams.get('tab')
    if (t && t !== tab) setTab(t)
  }, [searchParams])

  const handleTabChange = (t) => {
    setTab(t)
    setSearchParams({ tab: t })
  }

  const newsQuery       = useQuery({ queryKey: ['content-news'],      queryFn: () => content.list(),       enabled: tab === 'news' })
  const hackathonsQuery = useQuery({ queryKey: ['content-hackathons'], queryFn: () => content.hackathons(), enabled: tab === 'hackathons' })
  const winnersQuery    = useQuery({ queryKey: ['content-winners'],   queryFn: () => content.winners(),    enabled: tab === 'winners' })

  const q = tab === 'news' ? newsQuery : tab === 'hackathons' ? hackathonsQuery : winnersQuery

  const createActions = {
    news:       () => navigate('/content/news/new'),
    hackathons: () => navigate('/content/hackathons/new'),
    winners:    () => navigate('/content/winners/new'),
    leadership: () => navigate('/content/leadership/new'),
    faqs:       () => navigate('/content/faqs/new'),
  }

  const actionLabel = {
    news:       'New Article',
    hackathons: 'New Hackathon Page',
    winners:    'Add Winner',
    leadership: 'Add Card',
    faqs:       'New FAQ',
  }

  const items = Array.isArray(q?.data) ? q.data : (q?.data?.results ?? [])

  return (
    <div className="p-6 space-y-6">
      <PageHeader
        title="Content Management"
        subtitle="Manage news, hackathon pages, winner spotlights, leadership carousel and FAQs"
        icon={<FileText size={20} />}
        actions={
          <button className="btn-primary flex items-center gap-1.5" onClick={createActions[tab]}>
            <Plus size={15} />
            {actionLabel[tab]}
          </button>
        }
      />

      <Tabs tabs={TABS} active={tab} onChange={handleTabChange} />

      {tab === 'leadership' && <LeadershipList embedded />}

      {tab === 'faqs' && <FaqList embedded />}

      {tab !== 'leadership' && tab !== 'faqs' && (
        <>
          {q?.isLoading && <SkeletonCards count={6} />}

          {q?.isError && (
            <ErrorState
              message={q.error?.message ?? 'Failed to load content'}
              onRetry={q.refetch}
            />
          )}

          {!q?.isLoading && !q?.isError && items.length === 0 && (
            <EmptyState
              icon={tab === 'winners' ? Trophy : Megaphone}
              title={tab === 'news' ? 'No articles yet' : tab === 'hackathons' ? 'No hackathon pages yet' : 'No winners yet'}
              message={
                tab === 'news'
                  ? 'Create news articles and announcements to show in the public Innovation Feed.'
                  : tab === 'hackathons'
                  ? 'Add rich content pages for hackathon programs.'
                  : 'Feature winning teams to showcase impact.'
              }
              action={
                <button className="btn-primary flex items-center gap-1.5" onClick={createActions[tab]}>
                  <Plus size={14} />
                  {actionLabel[tab]}
                </button>
              }
            />
          )}

          {!q?.isLoading && !q?.isError && items.length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4">
              {tab === 'news' && items.map(item => (
                <NewsCard key={item.id} item={item} onClick={() => navigate(`/content/news/${item.id}`)} />
              ))}
              {tab === 'hackathons' && items.map(item => (
                <HackathonCard key={item.id} item={item} onClick={() => navigate(`/content/hackathons/${item.id}`)} />
              ))}
              {tab === 'winners' && items.map(item => (
                <WinnerCard key={item.id} item={item} onClick={() => navigate(`/content/winners/${item.id}`)} />
              ))}
            </div>
          )}
        </>
      )}
    </div>
  )
}

import React, { useState, useEffect, useRef } from 'react'
import { useNavigate, useParams, useSearchParams, Link } from 'react-router-dom'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { ArrowLeft, Save, Trash2, Plus, X, Image, Upload, Crop } from 'lucide-react'
import PageHeader from '../../components/ui/PageHeader'
import SectionCard from '../../components/ui/SectionCard'
import ImageCropModal from '../../components/ui/ImageCropModal'
import Tabs from '../../components/ui/Tabs'
import { content, programs } from '../../lib/api/endpoints'
import { useConfirm } from '../../components/ui/confirm'

const EDITOR_TABS = [
  { key: 'overview',  label: 'Overview' },
  { key: 'prizes',    label: 'Prizes' },
  { key: 'faq',       label: 'FAQ' },
  { key: 'judges',    label: 'Judges' },
  { key: 'schedule',  label: 'Schedule' },
  { key: 'media',     label: 'Media' },
]

function Field({ label, required, children, hint }) {
  return (
    <div className="space-y-1.5">
      <label className="block text-xs font-semibold text-ceda-dark">
        {label}{required && <span className="text-red-500 ml-0.5">*</span>}
      </label>
      {children}
      {hint && <p className="text-[11px] text-ceda-muted">{hint}</p>}
    </div>
  )
}

function ListEditor({ items, onChange, fields, addLabel }) {
  const add = () => onChange([...items, Object.fromEntries(fields.map(f => [f.key, '']))])
  const update = (i, k, v) => onChange(items.map((item, idx) => idx === i ? { ...item, [k]: v } : item))
  const remove = (i) => onChange(items.filter((_, idx) => idx !== i))

  return (
    <div className="space-y-3">
      {items.map((item, i) => (
        <div key={i} className="bg-ceda-surface rounded-lg p-4 space-y-3 relative">
          <button
            className="absolute top-3 right-3 text-ceda-muted hover:text-red-500 transition-colors"
            onClick={() => remove(i)}
          >
            <X size={14} />
          </button>
          {fields.map(f => (
            <div key={f.key} className="space-y-1">
              <label className="text-[11px] font-semibold text-ceda-muted uppercase tracking-wide">{f.label}</label>
              {f.multiline ? (
                <textarea
                  className="input w-full text-sm resize-none"
                  rows={3}
                  value={item[f.key] ?? ''}
                  onChange={e => update(i, f.key, e.target.value)}
                  placeholder={f.placeholder ?? ''}
                />
              ) : (
                <input
                  className="input w-full text-sm"
                  value={item[f.key] ?? ''}
                  onChange={e => update(i, f.key, e.target.value)}
                  placeholder={f.placeholder ?? ''}
                />
              )}
            </div>
          ))}
        </div>
      ))}
      <button
        className="btn-ghost flex items-center gap-1.5 text-sm"
        onClick={add}
      >
        <Plus size={14} />{addLabel}
      </button>
    </div>
  )
}

function MediaSection({ detailId, mediaItems, onRefresh }) {
  const confirm = useConfirm()
  const fileRef = useRef()
  const [uploading, setUploading] = useState(false)
  const [caption, setCaption] = useState('')
  const [mediaError, setMediaError] = useState(null)

  async function handleUpload(e) {
    const file = e.target.files?.[0]
    if (!file || !detailId) return
    setUploading(true)
    setMediaError(null)
    const fd = new FormData()
    fd.append('hackathon_detail', detailId)
    fd.append('file', file)
    fd.append('caption', caption)
    fd.append('media_type', file.type.startsWith('video/') ? 'video' : 'photo')
    try {
      await content.uploadMedia(fd)
      setCaption('')
      onRefresh()
    } catch (err) {
      setMediaError(err?.response?.data?.detail ?? err?.message ?? 'Upload failed')
    } finally {
      setUploading(false)
      e.target.value = ''
    }
  }

  async function handleDelete(mediaId) {
    if (!(await confirm({ title: 'Remove this file?', body: 'It is taken off this hackathon page.', confirmLabel: 'Remove file' }))) return
    setMediaError(null)
    try {
      await content.deleteMedia(mediaId)
      onRefresh()
    } catch (err) {
      setMediaError(err?.response?.data?.detail ?? err?.message ?? 'Delete failed')
    }
  }

  return (
    <div className="space-y-5">
      {mediaError && (
        <div className="bg-red-50 border border-red-200 text-red-700 text-sm rounded-lg p-3 flex items-center gap-2">
          {mediaError}
          <button className="ml-auto" onClick={() => setMediaError(null)}><X size={12} /></button>
        </div>
      )}
      <SectionCard title="Upload Media">
        <div className="space-y-3">
          <Field label="Caption (optional)">
            <input className="input w-full" placeholder="Photo caption…" value={caption} onChange={e => setCaption(e.target.value)} />
          </Field>
          <button
            className="btn-ghost flex items-center gap-2"
            onClick={() => fileRef.current?.click()}
            disabled={uploading || !detailId}
          >
            <Upload size={14} />{uploading ? 'Uploading…' : 'Choose file'}
          </button>
          {!detailId && <p className="text-xs text-amber-600">Save the overview first before uploading media.</p>}
          <input ref={fileRef} type="file" accept="image/*,video/*" className="hidden" onChange={handleUpload} />
        </div>
      </SectionCard>

      {mediaItems.length > 0 && (
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
          {mediaItems.map(m => (
            <div key={m.id} className="relative group rounded-lg overflow-hidden border border-ceda-border">
              {m.media_type === 'photo' ? (
                <img src={m.file_url ?? m.file} alt={m.caption} className="w-full h-32 object-cover" />
              ) : (
                <video src={m.file_url ?? m.file} className="w-full h-32 object-cover" />
              )}
              <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                <button
                  className="text-white bg-red-500 rounded p-1.5"
                  onClick={() => handleDelete(m.id)}
                >
                  <Trash2 size={13} />
                </button>
              </div>
              {m.caption && (
                <p className="p-2 text-[11px] text-ceda-muted truncate">{m.caption}</p>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

export default function HackathonContentEditor() {
  const confirm = useConfirm()
  const { id } = useParams()
  const [searchParams] = useSearchParams()
  const preselectedProgram = searchParams.get('program') ?? ''
  const isNew = !id || id === 'new'
  const navigate = useNavigate()
  const qc = useQueryClient()
  const bannerRef = useRef()

  const [tab, setTab] = useState('overview')
  const [error, setError] = useState(null)
  const [savedId, setSavedId] = useState(isNew ? null : id)
  const [originProgram, setOriginProgram] = useState(preselectedProgram)

  const [form, setForm] = useState({
    program: preselectedProgram,
    theme: '',
    description: '',
    rules: '',
    eligibility: '',
    is_published: false,
  })
  const [bannerFile, setBannerFile] = useState(null)
  const [bannerPreview, setBannerPreview] = useState(null)
  const [cropSource, setCropSource] = useState(null)
  const [prizes, setPrizes] = useState([])
  const [faq, setFaq] = useState([])
  const [judges, setJudges] = useState([])
  const [schedule, setSchedule] = useState([])

  const { data: existing, isLoading, refetch } = useQuery({
    queryKey: ['hackathon-detail', savedId],
    queryFn: () => content.getHackathon(savedId),
    enabled: !!savedId && !isNew,
  })

  const { data: hackathonPrograms } = useQuery({
    queryKey: ['programs-hackathon'],
    queryFn: () => programs.list({ page_size: 100 }),
    select: (d) => (Array.isArray(d) ? d : d?.results ?? []).filter(p => {
      const code = typeof p.program_type === 'object' && p.program_type !== null
        ? p.program_type?.code
        : String(p.program_type ?? '')
      return code === 'hackathon' || code === 'innovation_challenge'
    }),
  })

  useEffect(() => {
    if (existing) {
      const programId = String(existing.program ?? '')
      setForm({
        program:      programId,
        theme:        existing.theme ?? '',
        description:  existing.description ?? '',
        rules:        existing.rules ?? '',
        eligibility:  existing.eligibility ?? '',
        is_published: existing.is_published ?? false,
      })
      setPrizes(existing.prizes ?? [])
      setFaq(existing.faq ?? [])
      setJudges(existing.judges ?? [])
      setSchedule(existing.schedule ?? [])
      if (existing.banner_image_url) setBannerPreview(existing.banner_image_url)
      if (!originProgram && programId) setOriginProgram(programId)
    }
  }, [existing])

  function buildFormData() {
    const fd = new FormData()
    fd.append('program', form.program)
    fd.append('theme', form.theme)
    fd.append('description', form.description)
    fd.append('rules', form.rules)
    fd.append('eligibility', form.eligibility)
    fd.append('is_published', form.is_published ? 'true' : 'false')
    fd.append('prizes', JSON.stringify(prizes))
    fd.append('faq', JSON.stringify(faq))
    fd.append('judges', JSON.stringify(judges))
    fd.append('schedule', JSON.stringify(schedule))
    if (bannerFile) fd.append('banner_image', bannerFile)
    return fd
  }

  const saveMutation = useMutation({
    mutationFn: () => {
      const fd = buildFormData()
      return savedId && !isNew ? content.updateHackathon(savedId, fd) : content.createHackathon(fd)
    },
    onSuccess: (data) => {
      qc.invalidateQueries({ queryKey: ['content-hackathons'] })
      const prog = originProgram || data.program
      if (prog) qc.invalidateQueries({ queryKey: ['hackathon-content-by-program', prog] })
      if (!savedId || isNew) {
        setSavedId(data.id)
        navigate(`/content/hackathons/${data.id}`, { replace: true })
      } else {
        refetch()
      }
    },
    onError: (err) => {
      setError(err?.response?.data?.detail ?? JSON.stringify(err?.response?.data) ?? 'Failed to save')
    },
  })

  const deleteMutation = useMutation({
    mutationFn: () => content.deleteHackathon(savedId),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['content-hackathons'] })
      navigate('/content')
    },
  })

  const selectedProgramItem = hackathonPrograms?.find(p => String(p.id) === String(form.program))
  const programLabel = String(existing?.program_title ?? selectedProgramItem?.title ?? '')

  if (!isNew && isLoading) {
    return <div className="p-6 animate-pulse space-y-4">{[...Array(4)].map((_, i) => <div key={i} className="h-12 bg-ceda-surface rounded-lg" />)}</div>
  }

  return (
    <div className="p-6 space-y-6">
      <PageHeader
        title={isNew ? 'New Hackathon Page' : 'Edit Hackathon Page'}
        subtitle={programLabel || (isNew ? 'Select a hackathon program below' : 'Hackathon detail page')}
        icon={
          <ArrowLeft
            size={18}
            className="cursor-pointer"
            onClick={() => originProgram
              ? navigate(`/programs/${originProgram}`)
              : navigate('/content')
            }
          />
        }
        actions={
          <div className="flex items-center gap-2">
            {!isNew && savedId && (
              <button
                className="btn-ghost text-red-500 hover:bg-red-50 flex items-center gap-1.5"
                onClick={async () => { if (await confirm({ title: 'Delete this hackathon page?', note: 'This cannot be undone.', confirmLabel: 'Delete page' })) deleteMutation.mutate() }}
                disabled={deleteMutation.isPending}
              >
                <Trash2 size={14} />Delete
              </button>
            )}
            {savedId && form.is_published && (
              <a
                href={`${import.meta.env.VITE_PUBLIC_URL ?? ''}/hackathons/${originProgram || form.program || savedId}`}
                target="_blank"
                rel="noreferrer"
                className="btn-ghost flex items-center gap-1.5 text-[#A01E0A]"
              >
                <Save size={14} style={{ transform: 'rotate(-45deg)' }} />View Public Page
              </a>
            )}
            <button
              className="btn-primary flex items-center gap-1.5"
              onClick={() => saveMutation.mutate()}
              disabled={saveMutation.isPending || !form.program}
            >
              <Save size={14} />
              {saveMutation.isPending ? 'Saving…' : 'Save'}
            </button>
          </div>
        }
      />

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 text-sm rounded-lg p-3 flex items-center gap-2">
          {error}
          <button className="ml-auto" onClick={() => setError(null)}><X size={12} /></button>
        </div>
      )}

      <Tabs tabs={EDITOR_TABS} active={tab} onChange={setTab} />

      {tab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-5">
            <SectionCard title="Basic Info">
              <div className="space-y-4">
                <Field label="Hackathon / Innovation Challenge" required>
                  <select
                    className="input w-full"
                    value={form.program}
                    onChange={e => setForm(f => ({ ...f, program: e.target.value }))}
                  >
                    <option value="">Choose a hackathon or challenge</option>
                    {(hackathonPrograms ?? []).map(p => (
                      <option key={p.id} value={p.id}>{p.title}</option>
                    ))}
                  </select>
                </Field>
                <Field label="Theme / Tagline">
                  <input className="input w-full" placeholder="e.g. Innovating for Digital Inclusion" value={form.theme} onChange={e => setForm(f => ({ ...f, theme: e.target.value }))} />
                </Field>
                <Field label="Description">
                  <textarea className="input w-full resize-y" rows={6} placeholder="Public-facing overview of this hackathon…" value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} />
                </Field>
                <Field label="Rules">
                  <textarea className="input w-full resize-y font-mono text-sm" rows={8} placeholder="Rules and submission requirements…" value={form.rules} onChange={e => setForm(f => ({ ...f, rules: e.target.value }))} />
                </Field>
                <Field label="Eligibility">
                  <textarea className="input w-full resize-y text-sm" rows={4} placeholder="Who can enter, e.g. permanent CEDA employees, teams of up to 5…" value={form.eligibility} onChange={e => setForm(f => ({ ...f, eligibility: e.target.value }))} />
                </Field>
              </div>
            </SectionCard>
          </div>

          <div className="space-y-5">
            <SectionCard title="Banner Image">
              <div
                className="border-2 border-dashed border-ceda-border rounded-lg p-5 flex flex-col items-center justify-center gap-3 cursor-pointer hover:border-ceda-green transition-colors"
                onClick={() => bannerRef.current?.click()}
              >
                {bannerPreview ? (
                  <img src={bannerPreview} alt="banner" className="w-full aspect-[4/1] rounded object-cover" />
                ) : (
                  <>
                    <div className="w-10 h-10 rounded-full bg-ceda-surface flex items-center justify-center">
                      <Image size={18} className="text-ceda-muted" />
                    </div>
                    <p className="text-xs text-ceda-muted text-center">Click to upload banner</p>
                  </>
                )}
              </div>
              <input
                ref={bannerRef}
                type="file"
                accept="image/*"
                className="hidden"
                onChange={e => {
                  const f = e.target.files?.[0]
                  if (f) setCropSource({ src: URL.createObjectURL(f), name: f.name })
                  e.target.value = ''
                }}
              />
              {bannerPreview && (
                <div className="flex gap-2 mt-3">
                  <button type="button" className="btn-secondary btn-sm flex-1 justify-center" onClick={() => setCropSource({ src: bannerPreview, name: 'banner.jpg' })}>
                    <Crop size={13} /> Adjust &amp; crop
                  </button>
                  <button type="button" className="btn-ghost btn-sm" onClick={() => bannerRef.current?.click()}>Replace</button>
                </div>
              )}
              <p className="text-[11px] text-ceda-muted mt-2">Click Save after cropping to update the public page.</p>
              {cropSource && (
                <ImageCropModal
                  src={cropSource.src}
                  fileName={cropSource.name}
                  onCancel={() => setCropSource(null)}
                  onApply={(file) => {
                    setBannerFile(file)
                    setBannerPreview(URL.createObjectURL(file))
                    setCropSource(null)
                  }}
                />
              )}
            </SectionCard>

            <SectionCard title="Publishing">
              <label className="flex items-start gap-3 cursor-pointer">
                <input type="checkbox" className="mt-0.5 accent-ceda-green" checked={form.is_published} onChange={e => setForm(f => ({ ...f, is_published: e.target.checked }))} />
                <div>
                  <p className="text-sm font-medium text-ceda-dark">Published</p>
                  <p className="text-[11px] text-ceda-muted">Visible on the public hackathon detail page</p>
                </div>
              </label>
            </SectionCard>
          </div>
        </div>
      )}

      {tab === 'prizes' && (
        <SectionCard title="Prize Structure">
          <p className="text-xs text-ceda-muted mb-3">
            For Innovation Challenges, list prizes from first place down. Winners are picked automatically:
            the highest-scoring entry gets the first prize, and so on. The number of prizes is the number of winners (3 if none are listed).
          </p>
          <ListEditor
            items={prizes}
            onChange={setPrizes}
            addLabel="Add prize"
            fields={[
              { key: 'position', label: 'Position', placeholder: 'e.g. 1st Place' },
              { key: 'label',    label: 'Award label', placeholder: 'e.g. Grand Prize' },
              { key: 'amount',   label: 'Amount', placeholder: 'e.g. BWP 50,000' },
              { key: 'description', label: 'Description', placeholder: 'What the winner receives…', multiline: true },
            ]}
          />
        </SectionCard>
      )}

      {tab === 'faq' && (
        <SectionCard title="Frequently Asked Questions">
          <ListEditor
            items={faq}
            onChange={setFaq}
            addLabel="Add FAQ"
            fields={[
              { key: 'question', label: 'Question', placeholder: 'Question…' },
              { key: 'answer',   label: 'Answer', placeholder: 'Answer…', multiline: true },
            ]}
          />
        </SectionCard>
      )}

      {tab === 'judges' && (
        <SectionCard title="Judges / Panel">
          <ListEditor
            items={judges}
            onChange={setJudges}
            addLabel="Add judge"
            fields={[
              { key: 'name',     label: 'Full name', placeholder: 'Dr. Jane Doe' },
              { key: 'title',    label: 'Title / Organisation', placeholder: 'CTO at CEDA' },
              { key: 'bio',      label: 'Bio', placeholder: 'Short biography…', multiline: true },
              { key: 'photo_url',label: 'Photo URL (optional)', placeholder: 'https://…' },
            ]}
          />
        </SectionCard>
      )}

      {tab === 'schedule' && (
        <SectionCard title="Event Schedule / Timeline">
          <ListEditor
            items={schedule}
            onChange={setSchedule}
            addLabel="Add milestone"
            fields={[
              { key: 'date',        label: 'Date', placeholder: '2026-05-01' },
              { key: 'label',       label: 'Milestone label', placeholder: 'Registration Closes' },
              { key: 'description', label: 'Details (optional)', placeholder: 'Further information…', multiline: true },
            ]}
          />
        </SectionCard>
      )}

      {tab === 'media' && (
        <MediaSection
          detailId={savedId}
          mediaItems={existing?.media ?? []}
          onRefresh={refetch}
        />
      )}
    </div>
  )
}

import React, { useEffect, useMemo, useState } from 'react'
import { Link, useNavigate, useParams } from 'react-router-dom'
import { ArrowLeft, Calendar, ClipboardList, ExternalLink, FileText, GitBranch, Layers, Newspaper, Plus, Users, ExternalLink as LinkIcon } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import PageHeader from '../../components/ui/PageHeader'
import SectionCard from '../../components/ui/SectionCard'
import StatusPill from '../../components/ui/StatusPill'
import DataTable from '../../components/ui/DataTable'
import Tabs from '../../components/ui/Tabs'
import ErrorState from '../../components/ui/ErrorState'
import { SkeletonTable, SkeletonStatCards } from '../../components/ui/LoadingSkeleton'
import { useProgram, useProgramForm, useProgramSubmissions } from '../../lib/queries/programs'
import ProgramFormEditor from '../../components/programs/ProgramFormEditor'
import { programs as programsApi, content as contentApi } from '../../lib/api/endpoints'

function formatDate(value) {
  if (!value) return '—'
  return new Date(value).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })
}

function InfoItem({ label, value }) {
  return (
    <div className="py-2 border-b border-ceda-border/60 last:border-b-0">
      <p className="text-[11px] font-medium uppercase tracking-wide text-ceda-muted">{label}</p>
      <p className="text-sm text-ceda-dark mt-0.5">{value ?? '—'}</p>
    </div>
  )
}

const STATUS_OPTIONS = [
  { value: 'draft', label: 'Draft' },
  { value: 'published', label: 'Published' },
  { value: 'closed', label: 'Closed' },
  { value: 'archived', label: 'Archived' },
]

export default function ProgramDetail() {
  const { id } = useParams()
  const navigate = useNavigate()
  const [tab, setTab] = useState('overview')
  const [actionError, setActionError] = useState(null)
  const [actionState, setActionState] = useState(null)
  const [targetStatus, setTargetStatus] = useState('')
  const { data: program, isLoading, error, refetch } = useProgram(id)
  const { data: form } = useProgramForm(id)
  const { data: submissionsData, isLoading: submissionsLoading, error: submissionsError, refetch: refetchSubmissions } = useProgramSubmissions(id)

  const isHackathon = (() => {
    const pt = program?.program_type
    if (!pt) return false
    const code = typeof pt === 'object' ? pt.code : String(pt)
    return code === 'hackathon' || code === 'innovation_challenge'
  })()

  const { data: hackathonContent, isLoading: hackathonLoading } = useQuery({
    queryKey: ['hackathon-content-by-program', id],
    queryFn: () => contentApi.hackathons({ program: id }),
    enabled: !!id && isHackathon,
    select: (d) => {
      const items = Array.isArray(d) ? d : d?.results ?? []
      return items[0] ?? null
    },
  })

  const submissions = Array.isArray(submissionsData) ? submissionsData : submissionsData?.results ?? []
  const workflowDefinitions = program?.workflow_definitions ?? []
  const activeWorkflow = program?.active_workflow_definition

  const statusCounts = useMemo(() => {
    const counts = new Map()
    for (const item of submissions) {
      const key = item.current_status || 'unknown'
      counts.set(key, (counts.get(key) || 0) + 1)
    }
    return [...counts.entries()]
  }, [submissions])

  const runSetStatus = async () => {
    if (!targetStatus || targetStatus === program.status) return
    setActionError(null)
    setActionState(`set-status:${targetStatus}`)
    try {
      await programsApi.setStatus(id, { status: targetStatus })
      await refetch()
    } catch (err) {
      setActionError(err.message)
    } finally {
      setActionState(null)
    }
  }

  useEffect(() => {
    if (program?.status) setTargetStatus(program.status)
  }, [program?.status])

  if (isLoading) {
    return (
      <div className="animate-fade-in">
        <SkeletonStatCards count={4} />
        <div className="mt-6"><SkeletonTable rows={5} cols={4} /></div>
      </div>
    )
  }

  if (error) {
    return <ErrorState message={error.message} onRetry={refetch} />
  }

  if (!program) {
    return <ErrorState message="Program not found." onRetry={refetch} />
  }

  return (
    <div className="animate-fade-in">
      <PageHeader
        title={program.title}
        subtitle={program.program_type?.name ?? 'Program'}
        back={
          <button onClick={() => navigate('/programs')} className="btn-ghost btn-sm -ml-2">
            <ArrowLeft size={14} /> Programs
          </button>
        }
        badge={<StatusPill status={program.status} />}
        actions={
          <>
            <select
              className="input h-9 py-0 text-sm w-36"
              value={targetStatus || program.status}
              onChange={(e) => setTargetStatus(e.target.value)}
            >
              {STATUS_OPTIONS.map((opt) => (
                <option key={opt.value} value={opt.value}>{opt.label}</option>
              ))}
            </select>
            <button className="btn-secondary btn-sm" disabled={!!actionState || (targetStatus || program.status) === program.status} onClick={runSetStatus}>
              {String(actionState || '').startsWith('set-status:') ? 'Saving Status…' : 'Set Status'}
            </button>
            <button className="btn-primary btn-sm" onClick={() => navigate(`/programs/${program.id}/edit`)}>
              Edit Program
            </button>
          </>
        }
      />

      {actionError && (
        <div className="mb-5 rounded-xl border border-ceda-red/20 bg-ceda-red-pale px-4 py-3 text-sm text-ceda-red">
          {actionError}
        </div>
      )}

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        {[
          { label: 'Submissions', value: submissions.length, icon: ClipboardList },
          { label: 'Form Fields', value: form?.fields?.length ?? 0, icon: FileText },
          { label: 'Workflow Versions', value: workflowDefinitions.length, icon: GitBranch },
          { label: 'Max Team Size', value: program.max_team_size ?? '—', icon: Users },
        ].map((item) => {
          const Icon = item.icon
          return (
            <div key={item.label} className="card p-4 flex items-center gap-3">
              <div className="w-9 h-9 rounded-lg bg-ceda-surface flex items-center justify-center flex-shrink-0">
                <Icon size={17} className="text-ceda-forest" />
              </div>
              <div>
                <p className="text-lg font-bold text-ceda-dark leading-none">{item.value}</p>
                <p className="text-xs text-ceda-muted mt-0.5">{item.label}</p>
              </div>
            </div>
          )
        })}
      </div>

      <Tabs
        tabs={[
          { key: 'overview', label: 'Overview' },
          { key: 'form', label: 'Submission Form', count: form?.fields?.length ?? 0 },
          { key: 'workflow', label: 'Workflow', count: workflowDefinitions.length },
          { key: 'submissions', label: 'Submissions', count: submissions.length },
          ...(isHackathon ? [{ key: 'public_content', label: 'Public Content' }] : []),
        ]}
        active={tab}
        onChange={setTab}
        className="mb-5"
      />

      {tab === 'overview' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
          <div className="lg:col-span-2 space-y-5">
            <SectionCard title="Program Timeline">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <InfoItem label="Opening Date" value={formatDate(program.opening_date)} />
                <InfoItem label="Closing Date" value={formatDate(program.closing_date)} />
                <InfoItem label="Screening Start" value={formatDate(program.screening_start)} />
                <InfoItem label="Screening End" value={formatDate(program.screening_end)} />
                <InfoItem label="Judging Start" value={formatDate(program.judging_start)} />
                <InfoItem label="Judging End" value={formatDate(program.judging_end)} />
                <InfoItem label="Event Date" value={formatDate(program.event_date)} />
                <InfoItem label="Public Visibility" value={program.is_public ? 'Visible publicly' : 'Staff only'} />
              </div>
            </SectionCard>

            <SectionCard title="Submission Rules">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <InfoItem label="Allow Team Submission" value={program.allow_team_submission ? 'Yes' : 'No'} />
                <InfoItem label="Allow Individual Submission" value={program.allow_individual_submission ? 'Yes' : 'No'} />
                {program.terms_and_conditions ? (
                  <div className="py-2 border-b border-ceda-border/60 last:border-b-0">
                    <p className="text-[11px] font-medium uppercase tracking-wide text-ceda-muted">Terms and Conditions</p>
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-sm text-ceda-dark">{program.terms_and_conditions.title}</span>
                      {program.terms_and_conditions.document_link && (
                        <a
                          href={program.terms_and_conditions.document_link}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-1 text-xs font-medium text-ceda-forest hover:underline flex-shrink-0"
                        >
                          <ExternalLink size={11} /> View
                        </a>
                      )}
                    </div>
                  </div>
                ) : (
                  <InfoItem label="Terms and Conditions" value="Not configured" />
                )}
              </div>
            </SectionCard>
          </div>

          <div className="space-y-5">
            <SectionCard title="Workflow">
              {activeWorkflow ? (
                <>
                  <InfoItem label="Active Definition" value={`${activeWorkflow.name} (v${activeWorkflow.version})`} />
                  <InfoItem label="Status" value={activeWorkflow.status} />
                  <Link className="btn-secondary btn-sm mt-3 inline-flex" to={`/admin/workflows/${activeWorkflow.id}/builder`}>
                    <GitBranch size={14} /> Open Runtime Workflow
                  </Link>
                </>
              ) : (
                <div className="space-y-3">
                  <p className="text-sm text-ceda-muted">No active workflow is linked to this program yet.</p>
                  <Link className="btn-primary btn-sm inline-flex" to="/admin/workflows">
                    <GitBranch size={14} /> Define Workflow
                  </Link>
                </div>
              )}
            </SectionCard>

            <SectionCard title="Submission Status Mix">
              {statusCounts.length === 0 ? (
                <p className="text-sm text-ceda-muted">No submissions yet.</p>
              ) : (
                <div className="space-y-2">
                  {statusCounts.map(([status, count]) => (
                    <div key={status} className="flex items-center justify-between gap-2">
                      <StatusPill status={status} dot={false} className="flex-1 justify-start" />
                      <span className="text-sm font-semibold text-ceda-dark">{count}</span>
                    </div>
                  ))}
                </div>
              )}
            </SectionCard>
          </div>
        </div>
      )}

      {tab === 'form' && <ProgramFormEditor programId={program.id} />}

      {tab === 'workflow' && (
        <SectionCard title="Workflow Definitions" subtitle="Runtime workflow versions available for this program.">
          {workflowDefinitions.length === 0 ? (
            <div className="space-y-3">
              <p className="text-sm text-ceda-muted">No workflow definitions exist yet for this program.</p>
              <Link className="btn-primary btn-sm inline-flex" to="/admin/workflows">
                <GitBranch size={14} /> Create Workflow
              </Link>
            </div>
          ) : (
            <div className="space-y-3">
              {workflowDefinitions.map((definition) => (
                <div key={definition.id} className="rounded-xl border border-ceda-border bg-white px-4 py-3 flex items-center justify-between gap-4">
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-ceda-dark truncate">{definition.name}</p>
                    <p className="text-xs text-ceda-muted">{definition.code} · Version {definition.version}</p>
                  </div>
                  <div className="flex items-center gap-2">
                    <StatusPill status={definition.status} />
                    <Link className="btn-secondary btn-sm" to={`/admin/workflows/${definition.id}/builder`}>
                      Open
                    </Link>
                  </div>
                </div>
              ))}
            </div>
          )}
        </SectionCard>
      )}

      {tab === 'public_content' && (
        <div className="space-y-5">
          {hackathonLoading ? (
            <div className="animate-pulse space-y-4">
              <div className="h-32 bg-ceda-surface rounded-xl" />
            </div>
          ) : hackathonContent ? (
            <>
              <div className="rounded-xl border border-ceda-border bg-white p-5 flex items-start gap-5">
                {hackathonContent.banner_image_url ? (
                  <img
                    src={hackathonContent.banner_image_url}
                    alt="banner"
                    className="w-28 h-20 rounded-lg object-cover flex-shrink-0 border border-ceda-border"
                  />
                ) : (
                  <div className="w-28 h-20 rounded-lg bg-ceda-surface flex items-center justify-center flex-shrink-0 border border-ceda-border">
                    <Newspaper size={22} className="text-ceda-muted" />
                  </div>
                )}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <p className="font-bold text-ceda-dark text-sm truncate">{hackathonContent.program_title}</p>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${hackathonContent.is_published ? 'bg-green-100 text-green-700' : 'bg-amber-100 text-amber-700'}`}>
                      {hackathonContent.is_published ? 'Published' : 'Draft'}
                    </span>
                  </div>
                  {hackathonContent.theme && (
                    <p className="text-[12px] text-ceda-muted mb-2 italic">"{hackathonContent.theme}"</p>
                  )}
                  <div className="flex flex-wrap gap-3 text-[11px] text-ceda-muted mt-1">
                    <span>{hackathonContent.prizes?.length ?? 0} prizes</span>
                    <span>·</span>
                    <span>{hackathonContent.faq?.length ?? 0} FAQ items</span>
                    <span>·</span>
                    <span>{hackathonContent.judges?.length ?? 0} judges</span>
                    <span>·</span>
                    <span>{hackathonContent.schedule?.length ?? 0} milestones</span>
                    <span>·</span>
                    <span>{hackathonContent.media?.length ?? 0} media files</span>
                  </div>
                </div>
                <Link
                  to={`/content/hackathons/${hackathonContent.id}`}
                  className="btn-primary btn-sm flex-shrink-0 flex items-center gap-1.5"
                >
                  <FileText size={13} /> Edit Public Content
                </Link>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
                {[
                  { label: 'Description', ok: !!hackathonContent.description },
                  { label: 'Rules', ok: !!hackathonContent.rules },
                  { label: 'Prizes', ok: (hackathonContent.prizes?.length ?? 0) > 0 },
                  { label: 'FAQ', ok: (hackathonContent.faq?.length ?? 0) > 0 },
                  { label: 'Schedule', ok: (hackathonContent.schedule?.length ?? 0) > 0 },
                  { label: 'Judges', ok: (hackathonContent.judges?.length ?? 0) > 0 },
                  { label: 'Banner', ok: !!hackathonContent.banner_image_url },
                  { label: 'Media', ok: (hackathonContent.media?.length ?? 0) > 0 },
                ].map(({ label, ok }) => (
                  <div key={label} className={`rounded-lg border px-3 py-2.5 flex items-center gap-2 ${ok ? 'border-green-200 bg-green-50' : 'border-ceda-border bg-ceda-surface'}`}>
                    <span className={`w-1.5 h-1.5 rounded-full flex-shrink-0 ${ok ? 'bg-green-500' : 'bg-gray-300'}`} />
                    <span className="text-[11px] font-semibold text-ceda-dark">{label}</span>
                    {!ok && <span className="ml-auto text-[10px] text-ceda-muted">Empty</span>}
                  </div>
                ))}
              </div>
            </>
          ) : (
            <SectionCard>
              <div className="text-center py-10">
                <div className="w-14 h-14 rounded-full bg-ceda-surface flex items-center justify-center mx-auto mb-4">
                  <Newspaper size={24} className="text-ceda-muted" />
                </div>
                <p className="font-semibold text-ceda-dark mb-1">No public content page yet</p>
                <p className="text-sm text-ceda-muted mb-6 max-w-sm mx-auto">
                  Create a public-facing content page for this hackathon. It will show prizes, rules, FAQ, judges, schedule, and a media gallery to participants.
                </p>
                <Link
                  to={`/content/hackathons/new?program=${id}`}
                  className="btn-primary inline-flex items-center gap-2"
                >
                  <Plus size={14} /> Create Public Content Page
                </Link>
              </div>
            </SectionCard>
          )}
        </div>
      )}

      {tab === 'submissions' && (
        <SectionCard title="Program Submissions" padding={false}>
          {submissionsLoading ? (
            <SkeletonTable rows={5} cols={4} />
          ) : submissionsError ? (
            <ErrorState message={submissionsError.message} onRetry={refetchSubmissions} />
          ) : (
            <DataTable
              columns={[
                { key: 'reference_number', label: 'Reference', width: 140 },
                { key: 'title', label: 'Title', sortable: true },
                { key: 'current_status', label: 'Status', width: 140, render: (value) => <StatusPill status={value} /> },
                { key: 'submitted_at', label: 'Submitted', width: 140, render: (value) => formatDate(value) },
              ]}
              data={submissions}
              onRowClick={(row) => navigate(`/submissions/${row.id}`)}
              emptyTitle="No submissions yet"
              emptyMessage="Applications for this program will appear here."
            />
          )}
        </SectionCard>
      )}
    </div>
  )
}
